// 金币跑者:玩家行为
const COIN_MAGNET_RADIUS = 28;
const COIN_COLLECT_RADIUS = 12;
const COIN_MAGNET_STRENGTH = 0.25;

function movePlayer(player, input, dt) {
  // 移动逻辑占位:加速度 800,最大速度 240,摩擦 0.85(见 TECH_DESIGN v1)
  return player;
}

function collectCoins(player, coins) {
  let collected = 0;

  for (let index = coins.length - 1; index >= 0; index -= 1) {
    const coin = coins[index];
    const dx = player.x - coin.x;
    const dy = player.y - coin.y;
    const distance = Math.hypot(dx, dy);

    if (distance > COIN_MAGNET_RADIUS) {
      continue;
    }

    if (distance > COIN_COLLECT_RADIUS) {
      coin.x += dx * COIN_MAGNET_STRENGTH;
      coin.y += dy * COIN_MAGNET_STRENGTH;
    }

    if (Math.hypot(player.x - coin.x, player.y - coin.y) <= COIN_COLLECT_RADIUS) {
      coins.splice(index, 1);
      collected += 1;
    }
  }

  if (collected > 0 && coins.length === 0 && typeof player.collectedCallback === 'function') {
    player.collectedCallback();
  }

  return collected;
}

